  category_title = EXCLUDED.category_title,
  title = EXCLUDED.title,
  subtitle = EXCLUDED.subtitle,
  icon_type = EXCLUDED.icon_type,
  accent_color = EXCLUDED.accent_color,
  required_stars = EXCLUDED.required_stars;
